import { ForbiddenException, Injectable, UnauthorizedException } from "@nestjs/common";
import { AuthSessionRepository } from "@ringee/database";
import type { AuthSessionReader, RingeeAuthPrincipal } from "@ringee/platform";

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

/**
 * Dormant until every consumer is migrated. Resolve on every request/stream revalidation.
 * A provider session is authentication only; current domain rows authorize Ringee.
 */
@Injectable()
export class AuthPrincipalService {
  constructor(private readonly sessions: AuthSessionRepository) {}

  async resolve(reader: AuthSessionReader, headers: Headers): Promise<RingeeAuthPrincipal> {
    const verified = await reader.getVerifiedSession(headers);
    if (!verified || !UUID.test(verified.id) || !UUID.test(verified.userId)) {
      throw new UnauthorizedException("Session unavailable");
    }
    const snapshot = await this.sessions.findPrincipalSnapshot(verified.id, verified.userId, new Date());
    if (!snapshot || snapshot.session.userId !== verified.userId ||
        snapshot.session.user.id !== verified.userId || snapshot.session.expiresAt.getTime() <= Date.now()) {
      throw new UnauthorizedException("Session unavailable");
    }
    const { session, membership } = snapshot;
    const user = session.user;
    const email = user.authEmail;
    const primary = user.emails.filter((row) => row.isPrimary);
    if (user.blockedAt !== null || !email || email !== email.trim().toLowerCase() ||
        !user.authName?.trim() || !user.encryptionKey ||
        primary.length !== 1 || primary[0].email !== email ||
        !user.authEmailVerified || primary[0].status !== "verified") {
      throw new ForbiddenException("Account unavailable");
    }
    const organizationId = session.activeOrganizationId;
    if (organizationId !== null && (!UUID.test(organizationId) || !membership ||
        membership.userId !== user.id || membership.organizationId !== organizationId ||
        membership.organization.id !== organizationId ||
        !["org:admin", "org:member"].includes(membership.role))) {
      // Never silently turn an invalid explicit organization into personal access.
      throw new ForbiddenException("Workspace unavailable");
    }
    const role = organizationId === null ? null : membership!.role as "org:admin" | "org:member";
    const dto = {
      user: { id: user.id, email, emailVerified: true, name: user.authName, imageUrl: user.imageUrl },
      organization: organizationId === null ? null : { ...membership!.organization, role: role! },
      phoneAccess: { required: user.phoneRequired, verified: user.phoneVerified && !!user.phoneNumber },
      expiresAt: session.expiresAt.toISOString(),
    };
    return { id: user.id, sessionId: session.id, activeOrgId: organizationId, activeOrgRole: role, canCall: user.canCall, dto };
  }

  /** Product routes must call this; onboarding routes may read the principal DTO. */
  requireProductAccess(principal: RingeeAuthPrincipal): void {
    if (principal.dto.phoneAccess.required && !principal.dto.phoneAccess.verified) {
      throw new ForbiddenException("Phone verification required");
    }
  }
}

