/** Lazy: importing configuration must not change the active Clerk startup contract. */
export function readBetterAuthConfiguration() {
  const secret = process.env.BETTER_AUTH_SECRET;
  if (!secret || secret.length < 32) throw new Error("BETTER_AUTH_SECRET must contain at least 32 characters");
  return {
    secret,
    baseURL: "https://calls-api.connectxmedia.com",
    trustedOrigins: [
      "https://calls-api.connectxmedia.com",
      "https://calls.connectxmedia.com",
      "https://os.connectxmedia.com",
      "https://marketing.connectxmedia.com",
    ],
  };
}

