const { copyFileSync, mkdirSync, existsSync } = require("node:fs");
const { resolve, join } = require("node:path");
const root = resolve(__dirname, "..");
const owner = process.argv[2];
if (!["packages/platform", "apps/backend", "apps/orchestrator"].includes(owner)) throw new Error("Unknown build owner");
const source = join(root, "packages/platform/src/auth/better-auth");
const destination = join(root, owner, "dist/packages/platform/src/auth/better-auth");
if (!existsSync(join(destination, "better-auth.runtime.js"))) throw new Error("Compile the native loader bridge before copying assets");
mkdirSync(destination, { recursive: true });
for (const name of ["native-loader.cjs", "runtime.mjs", "hashed-session-adapter.mjs"]) {
  copyFileSync(join(source, name), join(destination, name));
}

