import { describe, expect, it, vi } from "vitest";
import type { AuthSessionRepository } from "@ringee/database";
import { AuthPrincipalService } from "./auth-principal.service";

const USER = "10000000-0000-4000-8000-000000000001";
const SESSION = "20000000-0000-4000-8000-000000000001";
const ORG = "30000000-0000-4000-8000-000000000001";
function fixture() {
  const snapshot = {
    session: { id: SESSION, userId: USER, expiresAt: new Date(Date.now() + 60000), activeOrganizationId: null as string | null,
      user: { id: USER, authEmail: "enrolled@example.invalid", authName: "Enrolled", authEmailVerified: true,
        imageUrl: null, blockedAt: null as Date | null, encryptionKey: "synthetic-enrollment-key",
        phoneRequired: true, phoneVerified: true, phoneNumber: "+14165550100", canCall: false,
        emails: [{ email: "enrolled@example.invalid", status: "verified", isPrimary: true }] } },
    membership: null as null | { userId: string; organizationId: string; role: string; organization: { id: string; name: string; slug: null; imageUrl: null } },
  };
  const findPrincipalSnapshot = vi.fn(async () => snapshot);
  const service = new AuthPrincipalService({ findPrincipalSnapshot } as unknown as AuthSessionRepository);
  const reader = { getVerifiedSession: vi.fn(async () => ({ id: SESSION, userId: USER })) };
  return { snapshot, service, reader, findPrincipalSnapshot };
}
describe("canonical auth principal boundary", () => {
  it("returns canonical UUID personal scope without provider IDs or secrets", async () => {
    const f = fixture();
    const principal = await f.service.resolve(f.reader, new Headers());
    expect(principal.id).toBe(USER);
    expect(principal.activeOrgId).toBeNull();
    expect(principal.canCall).toBe(false);
    expect(principal.dto.organization).toBeNull();
    expect(JSON.stringify(principal)).not.toMatch(/clerkId|encryptionKey|token|password|privateMetadata/);
    expect(() => f.service.requireProductAccess(principal)).not.toThrow();
  });
  it("requires a verified provider session before database access", async () => {
    const f = fixture();
    await expect(f.service.resolve({ getVerifiedSession: async () => null }, new Headers())).rejects.toThrow("Session unavailable");
    await expect(f.service.resolve({ getVerifiedSession: async () => ({ id: "forged", userId: USER }) }, new Headers())).rejects.toThrow();
    expect(f.findPrincipalSnapshot).not.toHaveBeenCalled();
  });
  it.each(["blocked", "legacy", "unverified", "missingPrimary", "changedEmail", "missingInitialization"])("denies %s enrollment", async (reason) => {
    const f = fixture(), user = f.snapshot.session.user;
    if (reason === "blocked") user.blockedAt = new Date();
    if (reason === "legacy") user.authName = "";
    if (reason === "unverified") user.emails[0].status = "pending";
    if (reason === "missingPrimary") user.emails[0].isPrimary = false;
    if (reason === "changedEmail") user.authEmail = "changed@example.invalid";
    if (reason === "missingInitialization") user.encryptionKey = "";
    await expect(f.service.resolve(f.reader, new Headers())).rejects.toThrow("Account unavailable");
  });
  it("denies expired, revoked or mismatched database sessions", async () => {
    const f = fixture();
    f.snapshot.session.expiresAt = new Date(0);
    await expect(f.service.resolve(f.reader, new Headers())).rejects.toThrow("Session unavailable");
    f.snapshot.session.expiresAt = new Date(Date.now() + 60000);
    f.snapshot.session.userId = ORG;
    await expect(f.service.resolve(f.reader, new Headers())).rejects.toThrow("Session unavailable");
  });
  it("never falls back to personal when selected membership is invalid", async () => {
    const f = fixture();
    f.snapshot.session.activeOrganizationId = ORG;
    await expect(f.service.resolve(f.reader, new Headers())).rejects.toThrow("Workspace unavailable");
  });
  it("observes downgrade and revocation on the next request", async () => {
    const f = fixture();
    f.snapshot.session.activeOrganizationId = ORG;
    f.snapshot.membership = { userId: USER, organizationId: ORG, role: "org:admin", organization: { id: ORG, name: "Org", slug: null, imageUrl: null } };
    expect((await f.service.resolve(f.reader, new Headers())).activeOrgRole).toBe("org:admin");
    f.snapshot.membership.role = "org:member";
    expect((await f.service.resolve(f.reader, new Headers())).activeOrgRole).toBe("org:member");
    f.snapshot.membership.role = "super-org:admin";
    await expect(f.service.resolve(f.reader, new Headers())).rejects.toThrow("Workspace unavailable");
    f.snapshot.membership = null;
    await expect(f.service.resolve(f.reader, new Headers())).rejects.toThrow("Workspace unavailable");
    expect(f.findPrincipalSnapshot).toHaveBeenCalledTimes(4);
  });
  it("keeps phone onboarding mandatory and honors only the stored waiver", async () => {
    const f = fixture();
    f.snapshot.session.user.phoneVerified = false;
    const principal = await f.service.resolve(f.reader, new Headers());
    expect(() => f.service.requireProductAccess(principal)).toThrow("Phone verification required");
    f.snapshot.session.user.phoneRequired = false;
    expect(() => f.service.requireProductAccess(principal)).toThrow();
    const waived = await f.service.resolve(f.reader, new Headers());
    expect(() => f.service.requireProductAccess(waived)).not.toThrow();
  });
});

