const { test } = require("node:test");
const assert = require("node:assert/strict");
const { readFileSync, existsSync } = require("node:fs");
const { resolve, join } = require("node:path");
const { randomBytes } = require("node:crypto");
const root = resolve(__dirname, "..");
for (const owner of ["apps/backend", "apps/orchestrator"]) {
  test(owner + " compiled native ESM asset resolves pinned runtime", async () => {
    const directory = join(root, owner, "dist/packages/platform/src/auth/better-auth");
    assert.ok(existsSync(join(directory, "better-auth.runtime.js")), "Build the actual application first");
    const source = readFileSync(join(directory, "native-loader.cjs"), "utf8");
    assert.ok(source.includes('import("./runtime.mjs")'));
    assert.ok(!source.includes('require("better-auth'));
    const { createRuntime } = await require(join(directory, "native-loader.cjs")).loadRuntime();
    const configuration = { secret: randomBytes(48).toString("base64url"),
      baseURL: "https://calls-api.connectxmedia.com",
      trustedOrigins: ["https://calls.connectxmedia.com"] };
    assert.throws(() => createRuntime({}, { ...configuration, secret: "" }));
    assert.throws(() => createRuntime({}, { ...configuration, trustedOrigins: ["https://evil.connectxmedia.com"] }));
    assert.throws(() => createRuntime({}, { ...configuration, baseURL: "http://calls-api.connectxmedia.com" }));
    const runtime = createRuntime({}, configuration);
    for (const path of ["sign-up/email", "reset-password", "request-password-reset", "change-password", "get-session", "organization/create", "delete-user"]) {
      const response = await runtime.handle(new Request(configuration.baseURL + "/api/auth/" + path, { method: "POST" }));
      assert.equal(response.status, 404);
    }
    for (const origin of [undefined, "https://evil.connectxmedia.com", "https://calls.connectxmedia.com.evil.invalid"]) {
      const response = await runtime.handle(new Request(configuration.baseURL + "/api/auth/sign-out",
        { method: "POST", headers: origin ? { origin } : {} }));
      assert.equal(response.status, 403);
    }
  });
}
